#define GFS_CURVED_TRANSFER_LIBRARY
#include "test_curved_transfer_v1.cpp"
/* Actual current source integral minus outgoing positive overlap integrals.
 * The own fragment is an implicit positive geometric complement, never a
 * list of negative quadrature points. No thermal/velocity compression. */
static std::vector<R> read_weights(const char *guard,const std::vector<curved_partition::Site> &site){std::string path=std::string(guard)+"/site_weights.csv";FILE *f=fopen(path.c_str(),"r");need(f,"guard's exact target weights");char header[80];need(fgets(header,sizeof(header),f),"weight header");std::vector<R> out;unsigned long long id;R w;while(fscanf(f,"%llu,%Lg\n",&id,&w)==2){need(out.size()<site.size() && site[out.size()].id==id,"same ordered weighted sites");out.push_back(w);}need(feof(f) && out.size()==site.size(),"all frozen target weights");fclose(f);return out;}
static std::vector<R> event_cuts(const char *guard,size_t it,const curved::Record &r){
    char path[1024];snprintf(path,sizeof(path),"%s/events_triangle%zu.csv",guard,it);FILE *f=fopen(path,"r");need(f,"accepted event-isolation witness");char header[256];need(fgets(header,sizeof(header),f),"event header");std::vector<R> cuts=radial_cuts(r);R minimum=cuts.front(),maximum=cuts.back();int kind,i,j,k,depth;R xl,xh,yl,yh,lo,hi;while(fscanf(f,"%d,%d,%d,%d,%Lg,%Lg,%Lg,%Lg,%Lg,%Lg,%d\n",&kind,&i,&j,&k,&xl,&xh,&yl,&yh,&lo,&hi,&depth)==11){if(lo<=maximum && hi>=minimum){cuts.push_back(std::max(lo,minimum));cuts.push_back(std::min(hi,maximum));}}need(feof(f),"complete event witness rows");fclose(f);std::sort(cuts.begin(),cuts.end());cuts.erase(std::unique(cuts.begin(),cuts.end()),cuts.end());return cuts;
}
struct Piece {R lo,hi,error=0,ratio[NMOMENT]={},coarse_known=0,fine_known=0,coarse_unknown=0,fine_unknown=0,coarse_bound=0,fine_bound=0;int depth=0,worst_target=-1,worst_moment=-1;Row fine;std::vector<QuadPoint> points;};
struct ComplementRow {uint64_t triangle=0,source_index=0,evaluated=0,accepted=0,positive_points=0,unknown_points=0,root_panels=0;Moment source,outgoing[24],angular_uncertainty;R quadrature_ratio=0;int quadrature_complete=0;};
static ComplementRow complement(size_t it,const curved::Packet &p,const std::vector<curved_partition::Site> &site,const std::vector<R> &weights,const char *guard,std::vector<QuadPoint> &saved,const char *witness_directory=nullptr){
    const auto &r=p.record[it];ComplementRow out;out.triangle=it;for(size_t j=0;j<site.size();j++)if(site[j].id==r.cell)out.source_index=j;curved_bounds::Tri triangle;for(int a=0;a<3;a++)for(int k=0;k<2;k++)triangle[a][k]=r.triangle.geometry.x[a][k];auto bound=positive_source_bounds(r,triangle,p.parameters[3]);
    /* This evaluates the current stored map, not an old target CSV or IC
     * replacement. rho0 is the unchanged material reference density. */
    auto compiled=curved_compiled::compile(r,p.parameters[3]);auto candidate=source_candidates(r,bound,site,weights,out.source_index);std::vector<curved_partition::Site> own={site[out.source_index]};std::vector<R> own_weight={0};auto baseline=integrate(it,p,own,own_weight,24,16,nullptr,nullptr,&bound,false,&compiled);out.source=baseline.target[0];need(out.source.a[MASS]>0 && out.source.a[THERMAL]>0,"positive current source moments");if(candidate.size()==1){out.quadrature_complete=1;return out;}
    R M=out.source.a[MASS],U=out.source.a[THERMAL],v=hypotl(curved_bounds::absmax(bound.velocity[0]),curved_bounds::absmax(bound.velocity[1])),radius=0;for(auto x:triangle)radius=std::max(radius,hypotl(x[0],x[1]));R allowance[NMOMENT];for(auto &a:allowance)a=1e-12L*M;allowance[PX]=allowance[PY]=1e-12L*M*std::max(v,1e-30L);allowance[ANGULAR]=1e-12L*M*std::max(radius*v,1e-30L);allowance[KINETIC]=allowance[THERMAL]=allowance[POTENTIAL]=1e-10L*U;allowance[VOLUME]=1e-12L*r.triangle.geometry.area;allowance[QX]=allowance[QY]=1e-12L*M*std::max(radius,1e-30L);allowance[POLAR]=1e-12L*M*std::max(radius*radius,1e-30L);allowance[THERMAL_RATE]=1e-9L*U;
    auto evaluate=[&](R lo,R hi,int depth){Piece q;q.lo=lo;q.hi=hi;q.depth=depth;std::vector<R> interval={lo,hi};auto coarse=integrate(it,p,site,weights,8,12,nullptr,&interval,&bound,true,&compiled,&candidate);q.fine=integrate(it,p,site,weights,16,16,&q.points,&interval,&bound,true,&compiled,&candidate);out.evaluated++;need(!coarse.budget_failures && !q.fine.budget_failures,"bounded positive outgoing angular integration");for(int j=0;j<(int)site.size();j++)if(j!=(int)out.source_index)for(int k=0;k<NMOMENT;k++){
        /* Keep unresolved geometric bands separate from the quadrature
         * estimate; their entire positive contributions remain in output. */
        R a=coarse.target[j].a[k]-coarse.unknown_target[j].a[k],b=q.fine.target[j].a[k]-q.fine.unknown_target[j].a[k],error=8*fabsl(a-b)/allowance[k];q.ratio[k]=std::max(q.ratio[k],error);if(error>q.error){q.error=error;q.worst_target=j;q.worst_moment=k;q.coarse_known=a;q.fine_known=b;q.coarse_unknown=coarse.unknown_target[j].a[k];q.fine_unknown=q.fine.unknown_target[j].a[k];q.coarse_bound=coarse.angular_uncertainty.a[k];q.fine_bound=q.fine.angular_uncertainty.a[k];}}return q;};
    auto cuts=event_cuts(guard,it,r);std::vector<Piece> pieces;for(size_t j=0;j+1<cuts.size();j++)pieces.push_back(evaluate(cuts[j],cuts[j+1],0));const uint64_t cap=pieces.size()+256;
    while(true){R total=0,worst=0;int selected=-1;for(size_t j=0;j<pieces.size();j++){total+=pieces[j].error;if(pieces[j].depth<24 && pieces[j].error>worst){worst=pieces[j].error;selected=j;}}out.quadrature_ratio=total;if(total<=1){out.quadrature_complete=1;break;}if(selected<0 || out.evaluated+2>cap)break;R lo=pieces[selected].lo,hi=pieces[selected].hi,mid=lo+(hi-lo)/2;int depth=pieces[selected].depth+1;if(!(lo<mid && mid<hi))break;pieces.erase(pieces.begin()+selected);pieces.push_back(evaluate(lo,mid,depth));pieces.push_back(evaluate(mid,hi,depth));}
    std::sort(pieces.begin(),pieces.end(),[](const Piece &a,const Piece &b){return a.lo<b.lo;});out.accepted=pieces.size();for(auto &q:pieces){for(int j=0;j<(int)site.size();j++)sum(out.outgoing[j],q.fine.target[j]);sum(out.angular_uncertainty,q.fine.angular_uncertainty);out.positive_points+=q.fine.points;out.unknown_points+=q.fine.unknown_points;out.root_panels+=q.fine.root_panels;saved.insert(saved.end(),q.points.begin(),q.points.end());}
    if(witness_directory){const char *names[NMOMENT]={"mass","px","py","angular","K","U","volume","qx","qy","polar","thermal_rate","potential"};char path[1024];snprintf(path,sizeof(path),"%s/witness_panels_triangle%zu.csv",witness_directory,it);FILE *f=fopen(path,"w");need(f,"bounded per-panel cold-error witness");fprintf(f,"lo,hi,depth,error_ratio,worst_target,worst_moment,coarse_known,fine_known,coarse_unknown,fine_unknown,coarse_angular_bound,fine_angular_bound");for(auto name:names)fprintf(f,",ratio_%s",name);fprintf(f,"\n");for(const auto &q:pieces){fprintf(f,"%.21Lg,%.21Lg,%d,%.21Lg,%d,%s,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg",q.lo,q.hi,q.depth,q.error,q.worst_target,q.worst_moment>=0?names[q.worst_moment]:"none",q.coarse_known,q.fine_known,q.coarse_unknown,q.fine_unknown,q.coarse_bound,q.fine_bound);for(auto ratio:q.ratio)fprintf(f,",%.21Lg",ratio);fprintf(f,"\n");}fclose(f);}
    return out;
}
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(provided>=MPI_THREAD_FUNNELED,"MPI FUNNELED");int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);need(argc==5 || argc==6,"same packet/sites, accepted event guard, new output, optional single triangle");auto p=curved::read(argv[1]);auto site=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],site);auto start=std::chrono::steady_clock::now();
    if(argc==6){int it=atoi(argv[5]);need(ranks==1 && it>=0 && it<(int)p.record.size(),"bounded one-triangle preflight");std::vector<QuadPoint> points;auto q=complement(it,p,site,weights,argv[3],points,argv[4]);for(auto v:points)need(v.reference_weight>0 && v.rho0>0 && std::isfinite(v.reference_weight),"representable positive outgoing records");double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();printf("{\"scope\":\"single actual source triangle cold-error witness; not whole remap acceptance\",\"triangle\":%d,\"source_mass\":%.17Lg,\"source_U\":%.17Lg,\"positive_points\":%llu,\"evaluated_panels\":%llu,\"quadrature_estimate_ratio\":%.17Lg,\"quadrature_complete\":%s,\"angular_K_bound\":%.17Lg,\"angular_K_bound_over_U\":%.17Lg,\"seconds\":%.17g}\n",it,q.source.a[MASS],q.source.a[THERMAL],(unsigned long long)q.positive_points,(unsigned long long)q.evaluated,q.quadrature_ratio,q.quadrature_complete?"true":"false",q.angular_uncertainty.a[KINETIC],q.angular_uncertainty.a[KINETIC]/q.source.a[THERMAL],seconds);active_mpi=false;MPI_Finalize();return q.quadrature_complete?0:2;}
    std::vector<ComplementRow> row(p.record.size());std::vector<std::vector<QuadPoint>> points(p.record.size());
    #pragma omp parallel for schedule(dynamic,1)
    for(int it=0;it<(int)p.record.size();it++)if(it%ranks==rank)row[it]=complement(it,p,site,weights,argv[3],points[it]);
    char filename[1024];snprintf(filename,sizeof(filename),"%s/positive_outgoing_rank%d.bin",argv[4],rank);FILE *f=fopen(filename,"wb");need(f,"new positive outgoing packet");uint64_t count=0;for(const auto &v:points)count+=v.size();uint64_t header[6]={0x474650334f564c31ULL,1,(uint64_t)rank,(uint64_t)ranks,count,56};need(fwrite(header,sizeof(header),1,f)==1,"positive outgoing packet header");for(const auto &v:points)if(v.size())need(fwrite(v.data(),sizeof(QuadPoint),v.size(),f)==v.size(),"positive outgoing records");fclose(f);
    std::vector<ComplementRow> all(rank==0?row.size()*ranks:0);MPI_Gather(row.data(),row.size()*sizeof(ComplementRow),MPI_BYTE,all.data(),row.size()*sizeof(ComplementRow),MPI_BYTE,0,MPI_COMM_WORLD);bool estimate_pass=true;
    if(rank==0){for(size_t it=0;it<row.size();it++)row[it]=all[(it%ranks)*row.size()+it];Moment source[24],flux[24][24],target[24],uncertainty;uint64_t npoints=0,nunknown=0,complete=0,evaluated=0,accepted=0,roots=0;R maxQ=0;std::string path=std::string(argv[4])+"/complement_rows.csv";f=fopen(path.c_str(),"w");need(f,"complement quadrature ledger");fprintf(f,"triangle,source,quadrature_complete,evaluated,accepted,positive_points,unknown_points,quadrature_ratio,angular_mass_bound,angular_K_bound\n");for(const auto &v:row){sum(source[v.source_index],v.source);for(int j=0;j<24;j++)sum(flux[v.source_index][j],v.outgoing[j]);sum(uncertainty,v.angular_uncertainty);npoints+=v.positive_points;nunknown+=v.unknown_points;complete+=v.quadrature_complete;evaluated+=v.evaluated;accepted+=v.accepted;roots+=v.root_panels;maxQ=std::max(maxQ,v.quadrature_ratio);fprintf(f,"%llu,%llu,%d,%llu,%llu,%llu,%llu,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)v.triangle,(unsigned long long)site[v.source_index].id,v.quadrature_complete,(unsigned long long)v.evaluated,(unsigned long long)v.accepted,(unsigned long long)v.positive_points,(unsigned long long)v.unknown_points,v.quadrature_ratio,v.angular_uncertainty.a[MASS],v.angular_uncertainty.a[KINETIC]);}fclose(f);
        for(int i=0;i<24;i++){target[i]=source[i];for(int j=0;j<24;j++)if(j!=i)for(int k=0;k<NMOMENT;k++){target[i].a[k]-=flux[i][j].a[k];target[i].a[k]+=flux[j][i].a[k];}}
        path=std::string(argv[4])+"/source_outgoing_moments.csv";f=fopen(path.c_str(),"w");need(f,"source and shared outgoing moments");fprintf(f,"source,target,mass,px,py,angular,K,U,volume,qx,qy,polar,thermal_rate,potential\n");for(int i=0;i<24;i++)for(int j=0;j<24;j++){fprintf(f,"%llu,%llu",(unsigned long long)site[i].id,(unsigned long long)site[j].id);for(int k=0;k<NMOMENT;k++)fprintf(f,",%.21Lg",i==j?source[i].a[k]:flux[i][j].a[k]);fprintf(f,"\n");}fclose(f);
        path=std::string(argv[4])+"/target_moments.csv";f=fopen(path.c_str(),"w");need(f,"conservative positive-complement target moments");fprintf(f,"id,mass,px,py,angular,K,U,volume,qx,qy,polar,thermal_rate,potential,I,spin,Kint,Krot,Krest\n");Moment initial,total;R max_mass_drift=0,minrest=1e99L;bool positive=true;for(int j=0;j<24;j++){auto &a=target[j].a;sum(initial,source[j]);sum(total,target[j]);R I=a[POLAR]-(a[QX]*a[QX]+a[QY]*a[QY])/a[MASS],spin=a[ANGULAR]-(a[QX]*a[PY]-a[QY]*a[PX])/a[MASS],Kint=a[KINETIC]-(a[PX]*a[PX]+a[PY]*a[PY])/(2*a[MASS]),Krot=spin*spin/(2*I),rest=Kint-Krot;positive=positive && a[MASS]>0 && a[THERMAL]>0 && I>0;minrest=std::min(minrest,rest);max_mass_drift=std::max(max_mass_drift,fabsl(a[MASS]-source[j].a[MASS])/source[j].a[MASS]);fprintf(f,"%llu",(unsigned long long)site[j].id);for(R q:a)fprintf(f,",%.21Lg",q);fprintf(f,",%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",I,spin,Kint,Krot,rest);}fclose(f);
        R conservation=0;for(int k=0;k<NMOMENT;k++)conservation=std::max(conservation,fabsl(total.a[k]-initial.a[k])/(fabsl(initial.a[k])+initial.a[THERMAL]));estimate_pass=complete==row.size() && positive;double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();printf("{\"scope\":\"current source baseline plus once-computed positive outgoing overlaps; own domain retained as its positive predicate complement; actual resolved spin/rotation moments, no kinetic reservoir; no weight solve/compression/evolution\",\"ranks\":%d,\"OMP_threads\":%d,\"triangles\":%zu,\"quadrature_complete_triangles\":%llu,\"positive_outgoing_points\":%llu,\"uncertain_outgoing_points\":%llu,\"evaluated_panels\":%llu,\"accepted_panels\":%llu,\"root_panels\":%llu,\"max_quadrature_estimate_ratio\":%.17Lg,\"angular_mass_bound_at_radial_nodes\":%.17Lg,\"angular_K_bound_at_radial_nodes\":%.17Lg,\"angular_K_bound_over_total_U\":%.17Lg,\"max_target_mass_drift\":%.17Lg,\"global_moment_assembly_relative_residual\":%.17Lg,\"positive_m_U_I\":%s,\"minimum_resolved_Krest\":%.17Lg,\"quadrature_estimates_pass\":%s,\"complement_mass_matrix_positivity_proved\":false,\"full_cold_transfer_proved\":false,\"seconds\":%.17g}\n",ranks,omp_get_max_threads(),row.size(),(unsigned long long)complete,(unsigned long long)npoints,(unsigned long long)nunknown,(unsigned long long)evaluated,(unsigned long long)accepted,(unsigned long long)roots,maxQ,uncertainty.a[MASS],uncertainty.a[KINETIC],uncertainty.a[KINETIC]/initial.a[THERMAL],max_mass_drift,conservation,positive?"true":"false",minrest,estimate_pass?"true":"false",seconds);
    }int result=estimate_pass?1:0;MPI_Bcast(&result,1,MPI_INT,0,MPI_COMM_WORLD);active_mpi=false;MPI_Finalize();return result?0:2;
}
